js=js.replace("init().catch(e=>{window.error=e.stack;throw e});",'''let pending=false;function update(){if(!window.ready||pending)return;pending=true;requestAnimationFrame(async()=>{try{const yaw=Number(document.getElementById('yaw').value)*Math.PI/180;const zoom=Number(document.getElementById('zoom').value);const mode=document.getElementById('mode').value;const width=Math.min(1200,innerWidth),height=Math.min(1100,innerHeight-125);let target=[72,30,60],spanZ=145/zoom,rise=120,dist=260,extra={};if(mode==='facade'){target=[59,36,66];spanZ=70/zoom;rise=15;dist=200}if(mode==='river'){target=[80,12,42];spanZ=100/zoom;rise=95;dist=200;extra={cutY:20.9}}if(mode==='garden'){target=[99,9,86];spanZ=85/zoom;rise=55;dist=140}if(mode==='community'){target=[72,25,59];spanZ=118/zoom;rise=110;extra={cutY:29.9,minY:22}}if(mode==='ground'){target=[72,7,60];spanZ=140/zoom;rise=160;extra={cutY:11.9,minY:3}}if(mode==='section'){target=[65,33,60];spanZ=115/zoom;rise=90;extra={cutY:37.9}}let viewYaw=yaw;let eye=[target[0]+Math.sin(viewYaw)*dist,target[1]+rise,target[2]+Math.cos(viewYaw)*dist];if(mode==='top'){target=[72,4,60];eye=[72,400,60];spanZ=140/zoom}if(mode==='all')spanZ=Math.max(spanZ,200*height/width/zoom);if(mode==='top')spanZ=Math.max(spanZ,155*height/width/zoom);await window.render({width,height,spanZ,spanX:spanZ*width/height,eye,target,ortho:true,night:document.getElementById('night').checked,concept:false,...extra});document.getElementById('msg').textContent='NBT 同源几何 · 拖动旋转 · 玻璃及照明为近似预览';}catch(e){window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message}pending=false})}
for(const el of document.querySelectorAll('input,select'))el.addEventListener('input',update);let drag=null;cv.addEventListener('pointerdown',e=>{drag=[e.clientX,Number(document.getElementById('yaw').value)];cv.setPointerCapture(e.pointerId)});cv.addEventListener('pointermove',e=>{if(drag){document.getElementById('yaw').value=(drag[1]+(e.clientX-drag[0])*.5+720)%360;update()}});cv.addEventListener('pointerup',()=>drag=null);window.addEventListener('resize',update);init().then(update).catch(e=>{window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message});''')
viewer='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>市民服务中心 · NBT 几何查看</title><style>body{margin:0;background:#142f3c;color:#fff;font:13px system-ui}#controls{height:125px;padding:12px 18px;box-sizing:border-box}select{max-width:150px;padding:4px}label{display:inline-block;margin:4px 14px 4px 0}input[type=range]{width:100px;vertical-align:middle;accent-color:#5aa9ba}#c{display:block;touch-action:none}#msg{font-size:12px;color:#c5d7de}</style><div id="controls"><label>视图 <select id="mode"><option value="all">整体</option><option value="facade">幕墙</option><option value="river">大厅与连桥</option><option value="top">真俯视</option><option value="garden">入口竹园</option><option value="community">三层公共活动</option><option value="ground">首层受理与等候</option><option value="section">办公层剖切</option></select></label><label><input id="night" type="checkbox">夜景</label><label>旋转 <input id="yaw" type="range" min="0" max="360" value="45"></label><label>缩放 <input id="zoom" type="range" min="0.7" max="2" step="0.05" value="1"></label><div id="msg">加载内嵌几何…</div></div><canvas id="c"></canvas><script>'''+inject+js+'</script></html>'
