sections=[('lighting','嵌灯与园林'),('revision','内部分区'),('model','整栋'),('facade','错位立面'),('space','空间与内饰'),('views','日夜四面'),('download','下载'),('check','检查')]
body='<header><div class="hero"><div><div class="eyebrow">HAIBARA · HAF V0.3.3 · CEILING & LANDSCAPE</div><h1>市民服务中心</h1><p class="lead">灯光嵌入顶面，前庭形成完整园林<br>两格层间 · 七层全功能照明 · 竹林与水庭</p><span class="tag">保留错位窗沿</span><span class="tag">最终 NBT 回读</span><span class="tag">游戏实测待完成</span><div class="metrics"><div><b>39</b><small>功能空间有灯</small></div><div><b>22</b><small>原版竹子植株</small></div><div><b>168,775</b><small>非空气方块</small></div></div>'+dl(RUN/'building.nbt','下载 Civic.nbt','Civic.nbt')+'<a class="button" href="#model">查看模型</a></div>'+pic('landscape_day.png','R16 入口前庭：竹丛、树荫、廊架、水庭与连续步道。')+'</div></header>' 
body+='<nav>'+''.join('<a href="#'+id+'">'+txt+'</a>' for id,txt in sections)+'</nav><main>'
body+='<section id="lighting"><div class="eyebrow" style="color:#9b542b">V0.3.3 · R16</div><h2>灯面与吊顶齐平</h2><p>普通室内采用上格地板、下格吊顶与灯光的两格构造。上层完成面位置保持，原来突出的灯块被同平面的吊顶包围；楼梯洞口和室外连桥改用原板内嵌，保留原有通行净空。窗边留凹槽，保留已确认的窗区偏移和窗沿高差。</p><div class="grid">'+pic('service_eye_night.png','R13 同机位：灯块突出在单层楼板下。',LIGHT_BEFORE)+pic('service_eye_night.png','R16 同机位：灯面与下层吊顶齐平。')+'</div><div class="grid" style="margin-top:22px">'+pic('ceiling_eye.png','向上看灯具和吊顶交界，来自最终 NBT。')+pic('ceiling-section.png','直接截取最终 NBT：上格楼板与下格吊顶／灯块。',C/'review/readback')+'</div><p>新增 30,683 格吊顶；192 个边缘或楼梯附近灯块移入原有支承板。普通空间净高比原单层构造少一格（设计尺度 0.5 米），上层地板标高不变。七层 39 个功能空间全部有灯，以海晶灯、萤石等材料区分工作与休息氛围；原版光传播本身没有冷暖颜色。</p><h2>一整片前庭的空间组织</h2><div class="grid">'+pic('entrance_garden_day.png','R13：两组孤立方形花池，前庭联系较弱。',LIGHT_BEFORE)+pic('entrance_garden_day.png','R16：同机位查看竹丛、集散空间与廊架的关系。')+'</div><div class="grid" style="margin-top:22px">'+pic('landscape_day.png','全前庭日景：主入口、东入口与公园穿行线连续。')+pic('landscape_night.png','全前庭夜景：铺装嵌灯、池底灯与廊架末地烛。')+pic('landscape_plan.png','俯视核对通路宽度、池岸、木平台和停留位置。')+pic('lounge_eye_night.png','公共休息区夜景；仍保留柱梁和成组家具。')+'</div><p>入口集散区保持开敞；22 株竹子形成高低不同的片林，三株乔木配成组灌木与少量白花。浅池与观水木平台、坐凳组合，廊架提供另一处休息位置。旧粗大庭院灯和两只方池已移除。水池写入原版水源与完整底岸；本版没有鱼实体。</p><p class="note">预览为状态盒与近似光场，竹叶、玻璃和夜景光斑不等于原版实机效果。两个参考视频已读取作者、标题及可用简介／章节；播放与分镜图片未加载成功，未声称完整观看或照抄视频细节。</p><details><summary>逐层预览光场：R13 与当前</summary><p>完成面上方采样点的非零光场比例，仅用于发现暗区，不是游戏光级或照度认证。</p>'+table(['层','采样点','R13','R16'],[[str(b['floor'])+'F',b['samples'],str(a['positive_percent'])+'%',str(b['positive_percent'])+'%'] for a,b in zip(LV['before']['floors'],LV['after']['floors'])])+'</details></section>' 
body+='<section id="revision"><div class="eyebrow" style="color:#9b542b">V0.3.1 分区成果 · 当前延续</div><h2>先建立空间，再摆家具</h2><p>上一版用相近的桌椅和间距覆盖各层，留下大片同色地面。虽然有功能名称，视觉上仍像零散工位。此次用柱梁定出空间节奏，低柜、玻璃隔断与地面材质构成边界，沙发和共享桌围绕活动成组布置；主要通廊继续留空。</p><div class="grid">'+pic('community_interior.png','修改前 R06 · 三层家具孤立，公共活动与办公区的区别不清楚。',BEFORE)+pic('community_interior.png','当前 R16 · 阅读、交流、工作坊和活动桌形成各自的空间。')+'</div><h3>三层公共区近看</h3><div class="grid">'+pic('public_lounge_detail.png','沙发、茶几、花槽和木色地面形成休息组；柱子落在功能边缘。')+pic('lounge_eye.png','人视高度查看：柱梁、顶面灯带和矮柜共同限定范围，保留跨区视线。')+'</div>'+table(['楼层','空间组织','具体变化'],[['1F','受理与等候','连续受理柜台、成排等候座椅、填表桌、自助终端和咨询休息区'],['2F','安静等候与预约','面谈桌、阅读休息、活动教室；补通教室与交通核的内部入口'],['3F','公共交流与活动','沙发交流、阅读柜、工作坊、活动桌和茶歇；本层没有办公工位组'],['4–7F','工作与协作','工位合并成组，另设会议桌、储物边界和休息／茶水角']])+'<h3>首层与办公层的前后对照</h3><div class="grid">'+pic('ground_interior.png','首层修改前。',BEFORE)+pic('ground_interior.png','首层修改后：受理、等候和咨询围绕通廊成组。')+pic('upper_interior.png','办公层修改前。',BEFORE)+pic('upper_interior.png','办公层修改后：工位、会议与休息分开。')+'</div><p class="note">全楼写入 43 处功能地面区域、51 根视觉柱和 142 组家具／隔断模块，其中有 36 组沙发或长座椅、10 组办公桌。数量用于追溯，不代表装修完整度。柱子属于视觉分区构件，未进行真实承重计算。</p><p>窗区错位、窗沿长短及玻璃颜色保留。R10 曾有 9 个外窗玻璃片、此次相对 R13 又有 5 个玻璃片重算连接臂，窗的坐标和材质没有移动。15 个候选构件因碰撞或通行限制被省略，完整记录在过程文件中。</p></section>'
body+='<section id="model"><h2>按已确认的数据建造</h2><p>七层楼板、退台、挑空大厅、公园通道和二层连桥取自交接包。白色石英墙面、青色玻璃、少量蓝／深灰玻璃和上部橙色格栅按既定立面穿插。窗组 seed=20261026 的结果直接读取，没有重新抽取位置。</p><button id="startviewer">加载离线三维模型</button><iframe id="live" title="市民服务中心三维模型" hidden></iframe><p class="muted">支持旋转、缩放、日夜与分层查看。需要 WebGL 2 和 DecompressionStream；下方固定图片不依赖三维功能。方位为模型东 +X、北 −Z。</p></section>'
body+='<section id="facade"><h2>保留窗区与窗沿的错位</h2><div class="grid">'+pic('elevation-N.png','已确认 V0.3 背立面；画面左右已按设计镜像，不再反转。',C/'input/views')+pic('north_elevation.png','最终 NBT 背立面。主楼四层竖窗组右移、东翼三层窗带左移的构图保留。')+'</div><div class="grid" style="margin-top:22px">'+pic('window_detail.png','不等长窗沿、疏密不同的花槽与不同颜色玻璃。')+pic('facade_sample.png','东侧格栅和窗沿局部；薄玻璃片、顶半砖窗沿、外挑橙色竖格栅。')+'</div><p class="note"><b>75 组、401 个源窗矩形、113 段窗沿（87 段种植）全部有对应记录。</b>401 是设计矩形数量；不是 401 个彼此断开的实体窗洞。0.5 米网格使 181 对相邻细窗的窄分缝合并，逐项列在量化表中。窗组整体错位和窗沿长短没有改成整齐重复。</p>'+dl(C/'review/quantization.json','下载窗缝与标高量化差异','Civic_Quantization.json')+'</section>'
body+='<section id="space"><h2>空间关系与可进入内饰</h2><div class="grid">'+pic('hall_cut.png','大厅保留一、二层挑空；二层边界有栏板与按方案开窗的玻璃通廊。')+pic('bridge_cut.png','二层桥连续联系主楼与东翼；桥下中部几何净空为 9 格，即设计尺度约 4.5 米。')+'</div><p>三处交通核包含实际逐跑楼梯、平台、井道和静态电梯门。公共空间布置咨询台、办事桌、自助终端、等候座椅和导视构件；办公层布置桌椅与储物模块。沿用 39 个功能分区，重做为 142 组家具／隔断模块与 51 根视觉柱，保持公共通廊。功能分区尚未全部深化成独立装修房间，电梯尚不运行。</p><div class="grid">'+pic('ground_interior.png','首层切顶查看；受理柜台、等候座椅与公共休息分组布置。')+pic('upper_interior.png','中层办公切片；室内为适配深化，并非交接图中的精装细节。')+'</div><h3>逐层回读平面</h3><div>'+''.join('<button class="floorbutton" data-floor="'+str(i)+'">'+str(i)+'F</button>' for i in range(1,8))+'</div>'
for i in range(1,8):body+='<div class="planview" id="floor'+str(i)+'"'+(' hidden' if i!=1 else '')+'>'+pic('plan-'+str(i)+'.png',str(i)+'F 方块回读平面；设计路径叠加用于核对，非游戏自动寻路。',C/'review/readback')+'</div>'
body+='<div class="grid" style="margin-top:22px">'+pic('section-AA.png','AA：大厅与公园通道的实际方块截面。',C/'review/readback')+pic('section-BB.png','BB：二层连桥与核心区的实际方块截面。',C/'review/readback')+'</div><div class="grid" style="margin-top:22px">'+pic('top_day.png','真正交俯视：L 形与各处退台。')+pic('roof_detail.png','7 项指定设备、两组天线与屋顶出入口。机组和检修空间已留出。')+'</div></section>'
body+='<section id="views"><h2>四个等尺度 45° 日夜视角</h2><p>同一套相机参数比较四向；下列全部图片绑定最终 NBT 哈希。</p><div class="grid four">'+''.join(pic(q+'_day.png',q.upper()+' · 日景') for q in ['se','sw','ne','nw'])+'</div><div class="grid four" style="margin-top:22px">'+''.join(pic(q+'_night.png',q.upper()+' · 夜景') for q in ['se','sw','ne','nw'])+'</div><p class="muted">大厅／通廊固定灯与办公分区灯分别处理。夜景光场有外表扩散光斑，不能据此认定 Minecraft 的实际亮度和漏光表现。</p></section>'
body+='<section id="download"><h2>整栋文件与局部样板</h2>'+dl(RUN/'building.nbt','整栋 Civic.nbt','Civic.nbt')+dl(RUN/'materials.csv','材料表','Civic_Materials.csv')+dl(RUN/'params_used.json','建造参数','Civic_Parameters.json')+dl(RUN/'validation.json','检查报告','Civic_Validation.json')+'<p>七个样板均从最终 NBT 裁切并独立读回，可先检查细部：</p>'+''.join(dl(C/'samples/final'/(n+'.nbt'),label,n+'.nbt') for n,label in [('Facade','格栅与玻璃'),('Windows','错位窗与花槽'),('Bridge','二层连桥'),('Stairs','楼梯与电梯井'),('Public','三层公共休息区'),('Work','成组办公区'),('Garden','入口竹园与庭院灯')])+table(['项目','交付说明'],[['格式','Java Structure NBT · DataVersion 3955 · 目标 Java 1.21.1'],['包围盒','144 × 78 × 120 格（X × Y × Z），包含地台和边界留白'],['统一比例','1 米 = 2 格；主体约 120 × 96 格，主屋顶相对标高 60 格'],['放置','建议原点 Y=64；标准主世界允许原点 Y 在 −64..242；需支持此包围盒的导入工具'],['空气','稀疏 NBT 不清空未写入位置，使用空场地或预先清理范围'],['最终 NBT SHA-256',E(V['NBT_sha256'])]])+'</section>'
body+='<section id="check"><h2>已检查的范围</h2><p><b>23 项基础检查、15 项内部分区检查、12 项本轮吊顶与园林检查均通过。</b>新增原版竹子状态和细杆预览支持；39 项当前可执行核心测试通过，3 项旧案例测试因精简工程缺依赖而未执行，清单保留。包括独立 NBT 回读、状态与边界、窗区落地、窗沿承托、挑空、门洞、桥下净空、楼梯踏步上方采样净空、设备承托与逐层通廊到楼梯平台连通。几何采样不代替游戏碰撞、结构计算或完整寻路。</p><p>新增检查覆盖 39 个房间入口、95 个家具组的可达接近位置、通廊净空、柱子上下相接与冻结立面的差异。下一步先在原版无光影环境导入 Public / Work 样板，确认柱梁尺度、座椅观感、通行与灯光，再检查整栋。</p><details><summary>展开完整检查结果</summary>'+pre(V)+'</details><details><summary>本次内部分区检查</summary>'+pre(IV)+'</details></section></main><footer>2026-10-27 · HAF 0.3 案例适配 · 依据用户确认的 V0.3 原创设计</footer>'
body+='<script>const VIEWER="'+base64.b64encode(viewer.encode()).decode()+'";document.getElementById("startviewer").onclick=function(){const f=document.getElementById("live");f.hidden=false;f.srcdoc=new TextDecoder().decode(Uint8Array.from(atob(VIEWER),c=>c.charCodeAt(0)));this.hidden=true};for(const b of document.querySelectorAll(".floorbutton"))b.onclick=()=>{for(const p of document.querySelectorAll(".planview"))p.hidden=p.id!=="floor"+b.dataset.floor};</script>'
(O/'Civic.html').write_text(fontnotice+doc('市民服务中心 · HAF V0.3.3 嵌灯与完整前庭',body))
